def hex4(cp)
  cp <= 0xFFFF ? ("%04X" % cp) : ("%05X" % cp)
end

def glyph_font(cp)
  page = cp >> 7
  if (s = META[:mixed][page])
    b = s.getbyte((cp & 0x7F) >> 1)
    nib = (cp & 1) == 0 ? (b >> 4) : (b & 15)
    return nib == 15 ? nil : nib
  end
  if (a = META[:sparse][page])
    return nil if (a[1].getbyte((cp & 0x7F) >> 3) & (0x80 >> (cp & 7))) == 0
    return a[0]
  end
  META[:full][page]
end

def char_for(cp)
  return "." if cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)
  return "." if cp >= 0xD800 && cp <= 0xDFFF
  [cp].pack("U")
rescue RangeError
  "."
end

def block_label(a, b)
  names = []
  BLOCKS.each do |s, e, n|
    names << n if s <= b && e >= a
  end
  names.empty? ? "No Block" : names.join(" / ")
end

def page_glyphs(start)
  n = 0
  i = 0
  while i < 0x80
    n += 1 if glyph_font(start + i)
    i += 1
  end
  n
end

def draw_legend
  i = 0
  FONT_NAMES.each do |name|
    x = i < 5 ? 0 : 40
    y = 23 + (i % 5)
    bg = BG_COLORS[i] || 0
    fg = FG_COLORS[i] || 15
    a = Machine.tattr(fg, bg)
    Machine.text_put(x, y, "  ", a)
    Machine.text_put(x, y, i.to_s, a)
    Machine.text_put(x + 3, y, name, LEGEND_ATTR)
    i += 1
  end
end

def draw_page(page)
  start = page * 0x80
  finish = start + 0x7F
  count = page_glyphs(start)

  Machine.text_clear(Machine.tattr(15, 0))

  Machine.text_put(0, 0, "EmbFont16 viewer  [%s]" % META[:label], TITLE_ATTR)
  Machine.text_put(0, 1, "U+%s-U+%s   page %d/%d   glyphs %d/128" % [hex4(start), hex4(finish), page + 1, PAGE_COUNT, count], HEAD_ATTR)
  Machine.text_put(0, 2, "Block: " + block_label(start, finish), BLOCK_ATTR)

  Machine.text_put(GRID_X, GRID_Y, TL + (H + TT) * (CELLS_X - 1) + H + TR, GRID_ATTR)

  row = 0
  while row < CELLS_Y
    y = GRID_Y + 1 + row * 2
    Machine.text_put(0, y, "%05X" % (start + row * CELLS_X), ROW_ATTR)
    Machine.text_put(GRID_X, y, V + ("  " + V) * CELLS_X, GRID_ATTR)

    col = 0
    while col < CELLS_X
      cp = start + row * CELLS_X + col
      x = GRID_X + 2 + col * 4
      id = glyph_font(cp)
      if id
        bg = BG_COLORS[id] || 0
        fg = FG_COLORS[id] || 15
        a = Machine.tattr(fg, bg)
        Machine.text_put(x, y, "  ", a)
        Machine.text_put(x, y, char_for(cp), a)
      else
        Machine.text_put(x, y, "  ", MISS_ATTR)
        Machine.text_put(x, y, ".", MISS_ATTR)
      end
      col += 1
    end

    Machine.text_put(GRID_X, y + 1, ML + (H + MC) * (CELLS_X - 1) + H + MR, GRID_ATTR) if row < CELLS_Y - 1
    row += 1
  end

  Machine.text_put(GRID_X, GRID_Y + CELLS_Y * 2, BL + (H + BT) * (CELLS_X - 1) + H + BR, GRID_ATTR)

  Machine.text_put(0, 20, "Left/Right page  Up/Down 0x80  PgUp/PgDn 0x800  Home/End  q quit", HELP_ATTR)
  Machine.text_put(0, 21, "meta: %s   page %d/%d   U+%s-U+%s   glyphs %d/128" % [META[:label], page + 1, PAGE_COUNT, hex4(start), hex4(finish), count], STATUS_ATTR)
  Machine.text_put(0, 22, "Font origin (cell background):", STATUS_ATTR)
  draw_legend
end

Machine.mode = 1
Machine.text_visible = true

page = 0
draw_page(page)
Machine.vsync

loop do
  k = Machine.wait_key
  break if k.nil? || k < 0

  np = page
  case k
  when Machine::KEY_LEFT
    np -= 1 if np > 0
  when Machine::KEY_RIGHT
    np += 1 if np < MAX_PAGE
  when Machine::KEY_UP
    np -= 1 if np > 0
  when Machine::KEY_DOWN
    np += 1 if np < MAX_PAGE
  when Machine::KEY_PGUP
    np -= 16 if np >= 16
  when Machine::KEY_PGDN
    np += 16 if np <= MAX_PAGE - 16
  when Machine::KEY_HOME
    np = 0
  when Machine::KEY_END
    np = MAX_PAGE
  when 0x71, 0x51
    break
  end

  if np != page
    page = np
    draw_page(page)
    Machine.vsync
  end
end
